use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,io::Read,path::Path};
const R:&str="/home/ubuntu/src/zopro-perf-work/paired-cancel";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-28-paired-cancel";
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn main(){let r=Path::new(R);let d=Path::new(D);let mut index:BTreeMap<String,String>=serde_json::from_slice(&fs::read(d.join("artifact-index.json")).unwrap()).unwrap();for(f,h)in &index{assert_eq!(hash(d.join("artifacts").join(f)),*h);}let a:Value=serde_json::from_slice(&fs::read(r.join("analysis.json")).unwrap()).unwrap();assert_eq!(a["gate_passed"],true);let mut audits=BTreeMap::new();for label in["frozen","candidate"]{let path=r.join(format!("{label}-assembly.txt"));let text=fs::read_to_string(&path).unwrap();let mut selected=String::new();let mut records=Vec::new();let mut name=String::new();let mut lines=Vec::<String>::new();let mut emit=|name:&String,lines:&Vec<String>|{if["probe::chain","probe::streams","probe::fused"].iter().any(|p|name.contains(p)){selected.push_str(name);selected.push('\n');for l in lines{selected.push_str(l);selected.push('\n');}let frame:Vec<_>=lines.iter().filter(|l|{let w:Vec<_>=l.split_whitespace().collect();w.len()==3&&w[1]=="sub"&&w[2].starts_with('$')&&w[2].ends_with(",%rsp")}).collect();records.push(json!({"symbol":name,"literal_frame_subtractions":frame,"static_IFMA_sites":lines.iter().filter(|s|s.contains("vpmadd52")).count(),"RSP_operand_lines":lines.iter().filter(|s|s.contains("%rsp")).count()}));}};for line in text.lines(){if line.ends_with(">:"){emit(&name,&lines);name=line.into();lines.clear();}else if line.contains(':')&&!line.trim().is_empty(){lines.push(line.into());}}emit(&name,&lines);assert_eq!(records.len(),if label=="frozen"{12}else{24});fs::write(r.join(format!("{label}-hot.s")),selected).unwrap();audits.insert(label,json!({"full_objdump_sha256":hash(&path),"functions":records}));}
    fs::write(r.join("hot-code.json"),serde_json::to_vec_pretty(&json!({"status":"offline corrected literal-frame classification; no capture or original aggregate rerun","audits":audits})).unwrap()).unwrap();for f in["report.rs","bounds.md","hot-code.json","frozen-hot.s","candidate-hot.s"]{let source=r.join(f);let dest=d.join("artifacts").join(f);fs::copy(&source,&dest).unwrap();assert_eq!(hash(&source),hash(&dest));index.insert(f.into(),hash(dest));}fs::write(d.join("artifact-index.json"),serde_json::to_vec_pretty(&json!(index)).unwrap()).unwrap();println!("Report complete;{}artifact hashes;no captures repeated",index.len());}
